def fizz_buzz(n: int) -> int:
    """Return the number of times the digit 7 appears in integers less than n
    which are divisible by 11 or 13.
    """
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            s = str(i)
            count += s.count('7')
    return count

def prime_length(string):
    """Return True if the length of the string is a prime number, False otherwise."""
    n = len(string)
    if n < 2:
        return False
    # Check divisibility from 2 up to sqrt(n)
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def is_sorted(lst):
    from collections import Counter
    counts = Counter(lst)
    for count in counts.values():
        if count > 2:
            return False
    return lst == sorted(lst)

def move_one_ball(arr):
    n = len(arr)
    if n <= 1:
        return True

    count = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count += 1
            if count > 1:
                return False

    # If no break, it's already sorted
    if count == 0:
        return True

    # If exactly one break, check wrap-around condition
    return arr[-1] <= arr[0]

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Split by spaces and count occurrences
    counts = {}
    for ch in test.split():
        counts[ch] = counts.get(ch, 0) + 1

    if not counts:
        return {}

    # Find the maximum count
    max_count = max(counts.values())

    # Return all letters that have the maximum count
    return {letter: count for letter, count in counts.items() if count == max_count}

def minSubArraySum(nums):
    if not nums:
        raise ValueError("Input array must be non-empty")

    current_min = nums[0]
    global_min = nums[0]

    for x in nums[1:]:
        current_min = min(x, current_min + x)
        global_min = min(global_min, current_min)

    return global_min

def numerical_letter_grade(grades):
    """
    Convert a list of GPAs to letter grades based on the given scale.

    GPA       |    Letter grade
    4.0                A+
    > 3.7                A 
    > 3.3                A- 
    > 3.0                B+
    > 2.7                B 
    > 2.3                B-
    > 2.0                C+
    > 1.7                C
    > 1.3                C-
    > 1.0                D+ 
    > 0.7                D 
    > 0.0                D-
    0.0                E
    """
    def gpa_to_letter(gpa):
        if gpa == 4.0:
            return "A+"
        elif gpa > 3.7:
            return "A"
        elif gpa > 3.3:
            return "A-"
        elif gpa > 3.0:
            return "B+"
        elif gpa > 2.7:
            return "B"
        elif gpa > 2.3:
            return "B-"
        elif gpa > 2.0:
            return "C+"
        elif gpa > 1.7:
            return "C"
        elif gpa > 1.3:
            return "C-"
        elif gpa > 1.0:
            return "D+"
        elif gpa > 0.7:
            return "D"
        elif gpa > 0.0:
            return "D-"
        else:  # gpa == 0.0
            return "E"

    return [gpa_to_letter(g) for g in grades]

