def split_words(txt):
    # If there is any whitespace, split on whitespace
    if ' ' in txt or '\t' in txt or '\n' in txt or '\r' in txt:
        return txt.split()

    # If no whitespace, check for commas
    if ',' in txt:
        return txt.split(',')

    # If no whitespace and no commas, count lowercase letters with odd order
    # ord('a') = 0, ord('b') = 1, ..., ord('z') = 25
    # We want letters whose index (0–25) is odd: b, d, f, ..., y
    count = 0
    for ch in txt:
        if 'a' <= ch <= 'z':
            idx = ord(ch) - ord('a')
            if idx % 2 == 1:
                count += 1
    return count

def encrypt(s):
    """
    Encrypts a string by rotating the alphabet such that each letter
    shifts down by 4 positions (2 * 2) in the alphabet (wrapping around).

    Examples:
        encrypt('hi') -> 'lm'
        encrypt('asdfghjkl') -> 'ewhjklnop'
        encrypt('gf') -> 'kj'
        encrypt('et') -> 'ix'
    """
    shift = 4  # 2 * 2 = 4

    def shift_char(ch):
        """Helper function to shift a single character."""
        if 'a' <= ch <= 'z':
            offset = ord('a')
            return chr((ord(ch) - offset + shift) % 26 + offset)
        elif 'A' <= ch <= 'Z':
            offset = ord('A')
            return chr((ord(ch) - offset + shift) % 26 + offset)
        else:
            return ch

    return ''.join(shift_char(ch) for ch in s)

def fix_spaces(text: str) -> str:
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == ' ':
            # Count consecutive spaces
            j = i
            while j < n and text[j] == ' ':
                j += 1
            count = j - i

            if count == 1 or count == 2:
                result.append('_')
            else:
                result.append('-')

            i = j
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)

