def fibfib(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Base cases
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    # Iterative computation to avoid recursion depth issues
    a, b, c = 0, 0, 1  # fibfib(0), fibfib(1), fibfib(2)

    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c

    return c

def even_odd_palindrome(n: int):
    """
    Given a positive integer n, return a tuple (even_count, odd_count)
    representing the number of even and odd integer palindromes in [1, n].
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for x in range(1, n + 1):
        if is_palindrome(x):
            if x % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return even_count, odd_count

def rounded_avg(n, m):
    if n > m:
        return -1

    average = (n + m) / 2
    rounded = round(average)
    return bin(rounded)

def generate_integers(a, b):
    """
    Given two positive integers a and b, return the even digits between a
    and b, in ascending order.

    This interprets "even digits" as single-digit even numbers (0, 2, 4, 6, 8)
    that fall within the numerical range [min(a,b), max(a,b)].
    """
    start = min(a, b)
    end = max(a, b)

    even_digits = set()

    for n in range(start, end + 1):
        if n < 10 and n % 2 == 0:
            even_digits.add(n)

    return sorted(even_digits)

def any_int(x, y, z):
    # Check that all inputs are integers
    if not (isinstance(x, int) and isinstance(y, int) and isinstance(z, int)):
        return False

    # Check if one number equals the sum of the other two
    return (x == y + z) or (y == x + z) or (z == x + y)

def choose_num(x, y):
    # Ensure x <= y; if not, there's no valid range
    if x > y:
        return -1

    # Start from the largest number <= y and go down to x
    # We want the biggest even number, so start at y if even, else y-1
    start = y if y % 2 == 0 else y - 1

    if start < x:
        return -1

    return start
